export function initWritingAssistant({container,getState,getBilling,onChange}){
 const box=document.createElement('details');box.className='writing-assistant options-panel';box.innerHTML='<summary>Me ajude a escrever com IA</summary><p>Escolha uma ocasião e um tom. Você poderá revisar e editar a sugestão antes de usar.</p><p class="writing-access"></p><label>Ocasião<select class="writing-theme"><option value="aniversario">Aniversário</option><option value="namoro">Namoro</option><option value="familia">Família</option><option value="amizade">Amizade</option><option value="casamento">Presente para casal</option><option value="convite">Convite de casamento</option><option value="natal">Natal</option><option value="pascoa">Páscoa</option><option value="maes">Dia das Mães</option><option value="pais">Dia dos Pais</option></select></label><label>Tom<select class="writing-tone"><option value="carinhoso">Carinhoso</option><option value="alegre">Alegre</option><option value="simples">Simples e direto</option><option value="emocionante">Emocionante</option></select></label><label>Tipo de texto<select class="writing-target"><option value="message">Mensagem curta</option><option value="letter">Carta</option></select></label><label>Nome ou apelido (opcional)<input class="writing-name" maxlength="40" autocomplete="off"></label><label>Uma lembrança ou detalhe (opcional)<textarea class="writing-detail" rows="3" maxlength="280" placeholder="Ex.: nossas tardes na praia"></textarea></label><p>Nome, detalhe e opções escolhidas serão enviados à IA da NVIDIA para criar a sugestão. Não inclua dados sensíveis, senhas, códigos, telefone ou e-mail.</p><label class="writing-consent"><input type="checkbox" class="writing-allow"> Autorizo esse envio para gerar a sugestão.</label><button type="button" class="writing-generate">Gerar sugestão</button><p class="writing-status" role="status" aria-live="polite"></p><div class="writing-result" hidden><p class="writing-text"></p><button type="button" class="writing-apply">Usar e editar este texto</button></div>';container.append(box);
 const $=s=>box.querySelector(s),status=$('.writing-status'),result=$('.writing-result'),output=$('.writing-text'),button=$('.writing-generate');let version=0,view='',suggestion='',suggestionContext='';
 const record=()=>getBilling()?.find?.();const context=()=>JSON.stringify([getState().draftId||'',getState().format||'',record()?.id||'']);
 function clear(){version++;suggestion='';suggestionContext='';result.hidden=true;status.textContent='';button.disabled=false;}
 function render(){const current=context(),item=record(),available=item?.id&&item.status==='approved';$('.writing-access').textContent=available?'Disponível para este presente.':'Disponível após a confirmação da compra deste presente.';if(current!==view){view=current;clear();$('.writing-name').value='';$('.writing-detail').value='';$('.writing-allow').checked=false;}}
 for(const selector of ['.writing-theme','.writing-tone','.writing-target','.writing-name','.writing-detail','.writing-allow'])$(selector).addEventListener(['.writing-name','.writing-detail'].includes(selector)?'input':'change',clear);
 button.addEventListener('click',async()=>{const order=record(),state=getState();if(!order?.id||order.status!=='approved'){status.textContent='Confirme a compra deste presente para usar a sugestão.';return;}if(!$('.writing-allow').checked){status.textContent='Marque a autorização para gerar a sugestão.';return;}const personal=$('.writing-name').value+' '+$('.writing-detail').value;if(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/i.test(personal)||/\b(?:\d[\s.\-/]*){8,}\b/.test(personal)){status.textContent='Remova e-mail, telefone, códigos ou outros números sensíveis antes de enviar.';return;}const own=++version,started=context(),target=$('.writing-target').value;button.disabled=true;result.hidden=true;status.textContent='Criando sua sugestão…';try{const response=await fetch('/api/writing/suggest',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',...(order.accessKey?{Authorization:'Bearer '+order.accessKey}:{})},body:JSON.stringify({purchaseId:order.id,draftId:state.draftId,consent:true,theme:$('.writing-theme').value,tone:$('.writing-tone').value,format:state.format,target,nickname:$('.writing-name').value,detail:$('.writing-detail').value}),signal:AbortSignal.timeout(30000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Não foi possível gerar agora.');if(own!==version||started!==context())return;const text=typeof data.suggestion==='string'?data.suggestion.trim():'';if(!text||text.length>(target==='message'?180:2000))throw Error('A sugestão ficou longa demais. Tente gerar outra.');suggestion=text;suggestionContext=started;output.textContent=text;result.hidden=false;status.textContent='Sugestão pronta. Revise antes de usar.';}catch(error){if(own===version&&started===context())status.textContent=error.message||'Não foi possível gerar agora.';}finally{if(own===version)button.disabled=false;}});
 $('.writing-apply').addEventListener('click',()=>{if(!suggestion||suggestionContext!==context())return;const target=$('.writing-target').value,state=getState(),existing=target==='message'?state.message:state.experience?.letter;if(existing?.trim()&&!confirm('Substituir o texto atual por esta sugestão?'))return;const text=suggestion;clear();if(target==='message')onChange({message:text});else onChange({experience:{...state.experience,letter:text}});status.textContent='Sugestão aplicada. Você pode editar o texto.';});
 document.addEventListener('billing:change',render);render();return {render};
}
